1221	function lockWaitLimitMs(): number {
1222	  const raw = process.env.STOCKROOM_LOCK_WAIT_MS;
1223	  if (raw === undefined) return LOCK_WAIT_DEFAULT_MS;
1224	  // 必须整体是数字（含空白、小数点、符号均拒绝），避免把非法值悄悄解释为 0 或无限等待
1225	  if (!/^\d+$/.test(raw))
