1228	    );
1229	  const n = Number(raw);
1230	  if (!Number.isSafeInteger(n))
1231	    throw new UsageError(
1232	      `环境变量 STOCKROOM_LOCK_WAIT_MS 超出安全整数范围，拒绝启动（不能转换为无限等待）：${raw}`,
1233	    );
1234	  return n;
1235	}
