1237	function pidAlive(pid: number): boolean {
1238	  try {
1239	    process.kill(pid, 0);
1240	    return true;
1241	  } catch (e) {
1242	    return (e as NodeJS.ErrnoException).code === 'EPERM'; // 存在但无权发信号：视为存活
1243	  }
1244	}
