1250	/** 把（可能含符号链接的）数据目录归一为真实路径，使同一目录的不同写法共用一把锁。 */
1251	function resolveDataDir(dataDir: string): string {
1252	  try {
1253	    return realpathSync.native(dataDir);
1254	  } catch {
