1256	    const abs = resolve(dataDir);
1257	    const slash = Math.max(abs.lastIndexOf('/'), 0);
1258	    const parent = abs.slice(0, slash) || '/';
1259	    const base = abs.slice(slash + 1);
1260	    try {
1261	      return join(realpathSync.native(parent), base);
1262	    } catch {
1263	      return abs;
1264	    }
1265	  }
1266	}
