function tryBecomeCoordinator(dir: string, idPath: string): boolean {
  const coordPath = join(dir, LOCK_COORD);
  for (;;) {
    try {
      linkSync(idPath, coordPath);
      return true;
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EEXIST')
